{
  "name": "ART Access Register",
  "description": "Pharmacy dispensing data for ART patients - based on mamba fact tables",
  "uuid": "9ec815ed-e3ac-4710-a480-360e2777c7d1",
  "version": "0.2.0-v4-mamba",
  "status": "ACTIVE",
  "parameters": [
    {
      "name": "startDate",
      "label": "Start Date",
      "type": "DATE",
      "required": true
    },
    {
      "name": "endDate",
      "label": "End Date",
      "type": "DATE",
      "required": true
    }
  ],
  "baseCohortDefinition": {
    "type": "SQL",
    "name": "ART Access Patients",
    "config": {
      "sql": "SELECT DISTINCT e.client_id AS client_id\nFROM mamba_fact_encounter_hiv_art_card e\nJOIN mamba_fact_patients_latest_patient_demographics mdp\n  ON mdp.client_id = e.client_id\nWHERE\n  mdp.birthdate IS NOT NULL\n  AND mdp.gender IS NOT NULL\n  AND e.encounter_date BETWEEN :startDate AND :endDate\n  AND e.voided = 0"
    }
  },
  "dataSetDefinitions": [
    {
      "name": "ART_DISPENSING_LIST",
      "type": "PATIENT_DATA_SET",
      "rowFilter": {
        "type": "SQL",
        "name": "ART Access Patients",
        "config": {
          "sql": "SELECT DISTINCT e.client_id AS client_id\nFROM mamba_fact_encounter_hiv_art_card e\nJOIN mamba_fact_patients_latest_patient_demographics mdp\n  ON mdp.client_id = e.client_id\nWHERE\n  mdp.birthdate IS NOT NULL\n  AND mdp.gender IS NOT NULL\n  AND e.encounter_date BETWEEN :startDate AND :endDate\n  AND e.voided = 0"
        }
      },
      "columns": [
        {
          "name": "HIV Clinic No.",
          "dataDefinition": {
            "type": "IDENTIFIER",
            "config": {
              "identifierTypeUuid": "e1731641-30ab-102d-86b0-7a5022ba4115",
              "preferred": true
            }
          },
          "repeatResolution": {
            "strategy": "LATEST",
            "restrictToPeriod": false,
            "ignoreVoided": true
          },
          "key": "hiv_clinic_no"
        },
        {
          "name": "Full Name",
          "dataDefinition": {
            "type": "PERSON_NAME",
            "config": {
              "type": "FULL_NAME",
              "preferred": true
            }
          },
          "key": "full_name"
        },
        {
          "name": "Gender",
          "dataDefinition": {
            "type": "PERSON_ATTRIBUTE",
            "config": {
              "type": "GENDER"
            }
          },
          "key": "gender"
        },
        {
          "name": "Birth Date",
          "dataDefinition": {
            "type": "PERSON_ATTRIBUTE",
            "config": {
              "type": "BIRTHDATE"
            }
          },
          "key": "birth_date"
        },
        {
          "name": "Age",
          "dataDefinition": {
            "type": "CALCULATION",
            "config": {
              "calculation": "AGE",
              "onDate": ":startDate"
            }
          },
          "key": "age"
        },
        {
          "name": "Encounter Date",
          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT e.encounter_date FROM mamba_fact_encounter_hiv_art_card e WHERE e.client_id = :patientId AND e.encounter_date BETWEEN :startDate AND :endDate ORDER BY e.encounter_date DESC LIMIT 1"
            }
          },
          "repeatResolution": {
            "strategy": "LATEST",
            "restrictToPeriod": false,
            "ignoreVoided": false
          },
          "key": "encounter_date"
        },
        {
          "name": "Return Visit Date",
          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT e.return_visit_date FROM mamba_fact_encounter_hiv_art_card e WHERE e.client_id = :patientId AND e.return_visit_date BETWEEN :startDate AND :endDate ORDER BY e.return_visit_date DESC LIMIT 1"
            }
          },
          "repeatResolution": {
            "strategy": "LATEST",
            "restrictToPeriod": false,
            "ignoreVoided": false
          },
          "key": "return_visit_date"
        },
