              "conceptName": "CURRENT ARV REGIMEN",
              "strategy": "LATEST",
              "columnModifier": "MOST_RECENT",
              "returnDisplay": true,
              "extraValues": []
            }
          },
          "repeatResolution": {
            "strategy": "LATEST",
            "orderBy": "obs_datetime",
            "restrictToPeriod": true,
            "ignoreVoided": true
          },
