        {
          "name": "Complaints",
          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT GROUP_CONCAT(cn.name SEPARATOR ',') FROM obs o INNER JOIN concept_name cn ON o.value_coded = cn.concept_id WHERE o.person_id = :patientId AND o.concept_id = 90227 AND o.voided = 0 AND cn.locale = 'en' AND cn.concept_name_type = 'FULLY_SPECIFIED' AND o.obs_datetime BETWEEN :startDate AND :endDate"
            }
          },
