          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT c.name FROM cohort_member cm INNER JOIN cohort c ON cm.cohort_id = c.cohort_id INNER JOIN cohort_type ct ON c.cohort_type_id = ct.cohort_type_id WHERE cm.patient_id = :patientId AND ct.uuid = 'e50fa0af-df36-4a26-853f-feb05244e5ca' AND cm.voided = 0 ORDER BY cm.start_date DESC LIMIT 1"
            }
          },
